using FluentAssertions;using FuelFlow.Persistence;using FuelFlow.SharedKernel.Domain;using Microsoft.EntityFrameworkCore;using Xunit;namespace FuelFlow.IntegrationTests;/// <summary>/// <c>fuel_packages</c> modelled a volume as a product, duplicating one offer's per-litre pricing/// across every volume row. This suite covers the split into <c>fuel_offers</c> (the offer) and/// <c>fuel_offer_volumes</c> (the sizes it is sold in). Planning #318, finding F-33./// <para>/// <b>Nothing in the application reads the new tables yet</b> - that is PR B of the staged split. So/// none of these tests can go through a handler, and all of them talk to the database directly. That/// is deliberate: the claim under test is about the schema and the migration, and the only honest way/// to test a migration is to run it against a database that has rows to migrate./// </para>/// <para>/// The suite fixture builds its template by replaying every migration from zero, so the/// <c>fuel_packages</c> rows this backfill reads are the 32 seeded ones - all in the real pool, none/// in QA, none archived. That is thinner than production (13 real offers + 13 QA mirrors, some/// archived), so the cases production actually has and the fixture does not are constructed here/// explicitly rather than assumed./// </para>/// </summary>[Collection("Integration Tests")]public sealed class OfferBackfillIntegrationTests : IClassFixture<TestDatabaseFixture>{    private readonly TestDatabaseFixture _fixture;    public OfferBackfillIntegrationTests(TestDatabaseFixture fixture) => _fixture = fixture;    /// <summary>    /// Creates the fuels the offers in these tests point at.    /// <para>    /// <c>20261018104336</c> gave <c>fuel_offers</c> a real foreign key to <c>fuel_types</c>, so an offer    /// can no longer name a fuel that does not exist. That is the constraint earning its keep — an offer    /// with no fuel has no margin to read and prices nothing — but these tests invent fuel ids on the fly    /// to isolate one behaviour each, so the rows have to exist alongside.    /// </para>    /// <para>    /// Idempotent, and deliberately in one place: these ids are invented per test, and seeding them    /// from eight separate call sites is how one of them ends up missing.    /// </para>    /// </summary>    private async Task SeedReferencedFuelsAsync(ApplicationDbContext context)    {        await context.Database.ExecuteSqlRawAsync(            """            INSERT INTO fuel_types (id, name, brand_id, base_price, discount_price,                                    created_at_utc, updated_at_utc, is_deleted)            SELECT f.id, f.name, 'upg', 0, 0, now(), now(), false              FROM (VALUES                      ('upg-arch',    'ДП (arch)'),                      ('upg-keep',    'ДП (keep)'),                      ('upg-badpool', 'ДП (badpool)'),                      ('upg-dup',     'ДП (dup)'),                      ('upg-margin',  'ДП (margin)'),                      ('upg-neg',     'ДП (neg)'),                      ('upg-pool',    'ДП (pool)'),                      ('upg-vol',     'ДП (vol)')                   ) AS f(id, name)            ON CONFLICT (id) DO NOTHING            """);        context.ChangeTracker.Clear();    }    private ApplicationDbContext CreateContext()        => new(new DbContextOptionsBuilder<ApplicationDbContext>()            .UseNpgsql(_fixture.ConnectionString)            .Options, TestQrCipher.Instance);    // `EveryPackageRow_BecameExactlyOneVolume` and `VolumesKeepTheIdOfThePackageRowThey_Replace`    // are gone with `fuel_packages`. Both compared the old rows against the new ones directly -    // one volume per package row, and every volume keeping the id of the row it replaced - which is    // the backfill's central promise, and also only askable while the old rows exist.    //    // What is left in this file is the half that does not need them: every volume points at a real    // offer, no volume carries a per-litre column, the offers carry the pool, and the seed is    // self-consistent. Those are the properties that still have to hold on every row added from now    // on, which is the only part a test can still be responsible for.    [Fact]    public async Task EveryVolumeRow_PointedAtAnExistingOffer()    {        await using var context = CreateContext();        var orphans = await context.FuelOfferVolumes            .IgnoreQueryFilters()            .Where(v => !context.FuelOffers.IgnoreQueryFilters().Any(o => o.Id == v.OfferId))            .CountAsync();        orphans.Should().Be(0);    }    // `EveryOfferCarriesThePriceItsVolumeRowsAgreedOn` is gone with `fuel_packages`. It existed to    // catch a backfill that invented a price instead of copying one, by reading the old rows and    // comparing them to the offers they became - the only place in the suite where the old table was    // the subject rather than a leftover, and its own comment said it would go when the table did.    //    // The live question it was reaching for did not go with it. "Does a volume advertise the same    // price as the offer it belongs to?" is now asked before every deploy, in money rather than as a    // ratio, by deploy/preflight-db/010-offer-volume-price-agreement.sql - and by    // OfferVolumePriceAgreementTests. What was lost is only the ability to ask it of rows that no    // longer exist.    [Fact]    public async Task VolumesCarryNoPerLitrePricing()    {        // The reason the split exists. A per-litre column reachable from a volume row is a copy that        // can drift from the offer's, and nothing would detect it.        await using var context = CreateContext();        var columns = await context.Database.SqlQueryRaw<string>(            """            SELECT column_name AS "Value"            FROM information_schema.columns            WHERE table_name = 'fuel_offer_volumes'              AND (column_name LIKE '%price_per_liter%' OR column_name LIKE 'original_price')            """).ToListAsync();        columns.Should().BeEmpty("per-litre pricing belongs to the offer; the volume has litres and a package price");        // Four, not five: `final_price_per_liter` was dropped on 2026-10-17        // (`DeriveTheOfferFinalPrice`) because it was `min(cost + margin, pump - minDiscount)` stored        // beside the columns it is computed from, and every write path computed it that way before        // writing it. The offer now holds inputs only; the customer price is derived at read time. The        // listing still names its members rather than counting them, so a future stored copy of a        // derived figure cannot slip in unnoticed.        var offerColumns = await context.Database.SqlQueryRaw<string>(            """            SELECT column_name AS "Value"            FROM information_schema.columns            WHERE table_name = 'fuel_offers'              AND (column_name LIKE '%price_per_liter%'                   OR column_name IN ('margin_uah_per_liter', 'min_discount_per_liter'))            ORDER BY column_name            """).ToListAsync();        offerColumns.Should().BeEquivalentTo([            "margin_uah_per_liter",            "min_discount_per_liter",            "pump_price_per_liter",            "supplier_price_per_liter"        ], "cost, margin, pump and the minimum discount - inputs only; the price itself is derived");    }    [Fact]    public async Task TheOfferIds_AreExactlyWhatTheApplicationWouldCompute()    {        // The key derivation is stated three times - in OfferKeys and inline in the SQL of the two        // migrations that have to produce or repair these ids, because a migration cannot call into the        // assembly it migrates from. This is what keeps those copies from drifting apart. The ids here        // were written by SplitFuelPackagesIntoOffers under the older Brand-prefixed key and then        // re-keyed by DropTheBrandPrefixFromOfferKeys, so this asserts the end state both migrations        // had to agree on.        await using var context = CreateContext();        var rows = await context.FuelOffers.IgnoreQueryFilters()            .Select(o => new { o.Id, o.BrandId, o.FuelTypeId, o.DataKind })            .ToListAsync();        rows.Should().NotBeEmpty();        rows.Should().AllSatisfy(o =>            o.Id.Should().Be(OfferKeys.For(o.FuelTypeId, o.DataKind)));    }    [Fact]    public async Task EveryOffer_IsSoldByItsOwnFuelsBrand()    {        // The premise that lets the Brand stay out of the key: fuel_type_id is a primary key, so it        // identifies a fuel, and a fuel belongs to exactly one Brand - which is what makes the key        // unique. Nothing in the schema can enforce it (it is a fact about two tables), so it is a        // test here and deploy/preflight-db/012 before every pull. If this ever fails, the offer key is        // ambiguous and OfferKeys has to start spelling the Brand out again.        //        // Asked in SQL because FuelOffer has no navigation to the fuel type, which is the whole point:        // the two columns are related by an agreement, not by a foreign key.        await using var context = CreateContext();        var mismatched = await context.Database.SqlQueryRaw<string>(            """            SELECT o.id AS "Value"            FROM fuel_offers o            JOIN fuel_types f ON f.id = o.fuel_type_id            WHERE o.brand_id <> f.brand_id            """).ToListAsync();        mismatched.Should().BeEmpty("the offer's Brand is its fuel type's Brand, which is what makes the key unique");    }    [Fact]    public async Task ALiveFuelWithADuplicateName_IsRefusedAtTheSameBrand()    {        // The guard that the natural fuel id used to give for free. A second 'А-95' at OKKO used to        // collide on the primary key; the id is generated now, so without ux_fuel_types_Brand_name it        // would become a second offer and a second landing place for a parsed voucher.        await using var context = CreateContext();        var now = DateTime.UtcNow;        context.FuelTypes.Add(new FuelTypeEntity        {            Id = "twin-a",            BrandId = "upg",            Name = "А-95 (twin test)",            BasePrice = 50m,            DiscountPrice = 48m,            CreatedAtUtc = now,            UpdatedAtUtc = now        });        await context.SaveChangesAsync();        context.ChangeTracker.Clear();        context.FuelTypes.Add(new FuelTypeEntity        {            Id = "twin-b",            // different id, same (Brand, name)            BrandId = "upg",            Name = "А-95 (twin test)",            BasePrice = 50m,            DiscountPrice = 48m,            CreatedAtUtc = now,            UpdatedAtUtc = now        });        var act = async () => await context.SaveChangesAsync();        await act.Should().ThrowAsync<DbUpdateException>();        await context.Database.ExecuteSqlRawAsync("DELETE FROM fuel_types WHERE id IN ('twin-a', 'twin-b')");    }    [Fact]    public async Task AnArchivedFuel_FreesItsNameForAFreshOne()    {        // The index is partial on NOT is_deleted, so archiving takes a fuel out of the catalogue and        // releases the name. Asserted because the opposite - an archived twin blocking a catalogue the        // operator is trying to rebuild - is the failure mode a unique index silently acquires.        await using var context = CreateContext();        var now = DateTime.UtcNow;        context.FuelTypes.Add(new FuelTypeEntity        {            Id = "reused-a",            BrandId = "upg",            Name = "ДП (reuse test)",            BasePrice = 50m,            DiscountPrice = 48m,            IsDeleted = true,            DeletedAtUtc = now,            CreatedAtUtc = now,            UpdatedAtUtc = now        });        context.FuelTypes.Add(new FuelTypeEntity        {            Id = "reused-b",            BrandId = "upg",            Name = "ДП (reuse test)",            BasePrice = 50m,            DiscountPrice = 48m,            CreatedAtUtc = now,            UpdatedAtUtc = now        });        var act = async () => await context.SaveChangesAsync();        await act.Should().NotThrowAsync();        await context.Database.ExecuteSqlRawAsync("DELETE FROM fuel_types WHERE id IN ('reused-a', 'reused-b')");    }    [Fact]    public async Task OneOfferPerPool_EvenWhereTheSeedHasOnlyTheRealOne()    {        // Production has a QA mirror of every live offer; the seed has none. Constructed here so the        // case that matters - two offers differing only by pool - is actually covered rather than        // assumed, because if the suffix were dropped these two rows would collide on the unique        // index and the whole backfill would abort.        await using var context = CreateContext();        var now = DateTime.UtcNow;        await SeedReferencedFuelsAsync(context);        context.FuelOffers.Add(new FuelOffer        {            Id = OfferKeys.For("upg-pool", DataKinds.Real),            BrandId = "upg",            FuelTypeId = "upg-pool",            DataKind = DataKinds.Real,            SupplierPricePerLiter = 49m,            CreatedAtUtc = now,            UpdatedAtUtc = now        });        context.FuelOffers.Add(new FuelOffer        {            Id = OfferKeys.For("upg-pool", DataKinds.Qa),            BrandId = "upg",            FuelTypeId = "upg-pool",            DataKind = DataKinds.Qa,            SupplierPricePerLiter = 0.5m,            CreatedAtUtc = now,            UpdatedAtUtc = now        });        await context.SaveChangesAsync();        var pools = await context.FuelOffers.IgnoreQueryFilters()            .Where(o => o.BrandId == "upg" && o.FuelTypeId == "upg-pool")            .Select(o => o.DataKind).ToListAsync();        pools.Should().BeEquivalentTo(["real", "qa"]);    }    [Fact]    public async Task ASecondOfferForTheSameFuelAndPool_IsRefused()    {        // The natural key, enforced. Without it two offers for one (Brand, fuel, pool) would let        // the storefront's per-litre price become ambiguous again - the defect this whole split is// about, re-entering through the new tables.    await using var context = CreateContext();    await SeedReferencedFuelsAsync(context);        var now = DateTime.UtcNow;        context.FuelOffers.Add(new FuelOffer        {            Id = "dup-1",            BrandId = "upg",            FuelTypeId = "upg-dup",            DataKind = DataKinds.Real,            CreatedAtUtc = now,            UpdatedAtUtc = now        });        await context.SaveChangesAsync();        context.ChangeTracker.Clear();        context.FuelOffers.Add(new FuelOffer        {            Id = "dup-2",           // different id, same natural key            BrandId = "upg",            FuelTypeId = "upg-dup",            DataKind = DataKinds.Real,            CreatedAtUtc = now,            UpdatedAtUtc = now        });        var act = async () => await context.SaveChangesAsync();        await act.Should().ThrowAsync<DbUpdateException>();    }    [Fact]    public async Task ASameVolumeTwiceForOneOffer_IsRefused()    {        // THE guarantee of the split. The ambiguous checkout lookup that #315 had to resolve with an// ORDER BY cannot come back through these tables.    await using var context = CreateContext();    await SeedReferencedFuelsAsync(context);    var now = DateTime.UtcNow;        var offer = new FuelOffer        {            Id = "vol-offer",            BrandId = "upg",            FuelTypeId = "upg-vol",            DataKind = DataKinds.Real,            CreatedAtUtc = now,            UpdatedAtUtc = now        };        context.FuelOffers.Add(offer);        context.FuelOfferVolumes.Add(new FuelOfferVolume        {            Id = "vol-a",            OfferId = offer.Id,            Liters = 10m            CreatedAtUtc = now,            UpdatedAtUtc = now        });        await context.SaveChangesAsync();        context.ChangeTracker.Clear();        context.FuelOfferVolumes.Add(new FuelOfferVolume        {            Id = "vol-b",           // different id, same (offer, litres)            OfferId = offer.Id,            Liters = 10m            CreatedAtUtc = now,            UpdatedAtUtc = now        });        var act = async () => await context.SaveChangesAsync();        await act.Should().ThrowAsync<DbUpdateException>(            "a duplicate volume for one offer is the exact ambiguity this split exists to remove");    }    [Theory]    [InlineData(0)]    [InlineData(-10)]    public async Task ANonPositiveVolume_IsRefused(decimal liters)    {        // Reachable from the admin API: PUT .../nominals binds List<int> off the request body. #314        // closed this on fuel_packages; the bound has to come with the split or it is simply reopened.        await using var context = CreateContext();        var now = DateTime.UtcNow;        var offer = new FuelOffer        {            Id = $"neg-offer-{liters}",            BrandId = "upg",            FuelTypeId = "upg-neg",            DataKind = DataKinds.Real,            CreatedAtUtc = now,            UpdatedAtUtc = now        };        context.FuelOffers.Add(offer);        context.FuelOfferVolumes.Add(new FuelOfferVolume        {            Id = $"neg-vol-{liters}",            OfferId = offer.Id,            Liters = liters            CreatedAtUtc = now,            UpdatedAtUtc = now        });        var act = async () => await context.SaveChangesAsync();        await act.Should().ThrowAsync<DbUpdateException>();    }    [Fact]    public async Task ANegativeMargin_IsRefusedOnTheOffer()    {        // A negative margin is not a cheap mistake: the dashboard and the reconciliation report both        // multiply this straight into revenue, so a sign error there is a wrong number on a screen        // rather than a failed write.        await using var context = CreateContext();        var now = DateTime.UtcNow;        context.FuelOffers.Add(new FuelOffer        {            Id = "neg-margin-offer",            BrandId = "upg",            FuelTypeId = "upg-margin",            DataKind = DataKinds.Real,            CreatedAtUtc = now,            UpdatedAtUtc = now        });        var act = async () => await context.SaveChangesAsync();        await act.Should().ThrowAsync<DbUpdateException>();    }    [Fact]    public async Task AnUnknownPool_IsRefusedOnTheOffer()    {        await using var context = CreateContext();        var now = DateTime.UtcNow;        context.FuelOffers.Add(new FuelOffer        {            Id = "bad-pool-offer",            BrandId = "upg",            FuelTypeId = "upg-badpool",            DataKind = "sandbox",            CreatedAtUtc = now,            UpdatedAtUtc = now        });        var act = async () => await context.SaveChangesAsync();        await act.Should().ThrowAsync<DbUpdateException>();    }    [Fact]    public async Task ArchivingAVolume_DoesNotByItselfArchiveTheOffer()    {        // A caveat about what the schema does and does not guarantee, written as a test because the        // opposite of this is a natural assumption and an expensive one.        //        // The backfill derives the offer's own flag with bool_and(is_deleted): an offer follows its        // volumes out of the catalogue exactly when the last one is archived. That rule runs ONCE, in        // the migration. There is no trigger, so archiving a volume afterwards leaves the offer live.        //        // That is deliberate for this PR - nothing writes the new tables yet - and it becomes PR B/C's        // job to maintain the flag on every archive path (BrandsController's three loops and        // DeletePackageCommandHandler). A test that asserted "archiving the last volume archives the        // offer" would pass today only by asserting something false, so it asserts the real behaviour        // instead, and fails loudly if a trigger is ever added.        await using var context = CreateContext();        await context.Database.ExecuteSqlRawAsync(            """            INSERT INTO fuel_offers (id, brand_id, fuel_type_id, data_kind, supplier_price_per_liter,                                     margin_uah_per_liter, created_at_utc, updated_at_utc, is_deleted)            VALUES ('arch-offer', 'upg', 'upg-arch', 'real', 58, 2, now(), now(), false)            """);        await context.Database.ExecuteSqlRawAsync(            """            INSERT INTO fuel_offer_volumes (id, offer_id, liters, price_override_uah, is_deleted,                                           created_at_utc, updated_at_utc)            VALUES ('arch-vol-live', 'arch-offer', 10, 600, false, now(), now()),                   ('arch-vol-dead', 'arch-offer', 20, 1200, true,  now(), now())            """);        // One volume still on sale, so the offer is live - which is what the backfill's bool_and        // would have produced, and what the current schema still produces.        var offer = await context.FuelOffers.IgnoreQueryFilters().SingleAsync(o => o.Id == "arch-offer");        offer.IsDeleted.Should().BeFalse("one volume of this offer is still on sale");        await context.Database.ExecuteSqlRawAsync(            """UPDATE fuel_offer_volumes SET is_deleted = true WHERE id = 'arch-vol-live'""");        context.ChangeTracker.Clear();        var reloaded = await context.FuelOffers.IgnoreQueryFilters().SingleAsync(o => o.Id == "arch-offer");        reloaded.IsDeleted.Should().BeFalse(            "no trigger maintains this; the archive paths in PR C have to. If this ever becomes true, " +            "PR C's write paths should stop updating the offer flag by hand");    }    [Fact]    public async Task AnArchivedVolume_StaysReadable()    {        // The reason volumes carry their own is_deleted rather than inheriting the offer's: an offer        // keeps selling while one size leaves the catalogue, and an archived volume still has to be        // readable for the reports that resolve an order line back to what was bought.        //        // Its own rows rather than the previous test's, because the whole class shares one database        // and xUnit does not promise an order - reading a neighbour's rows would make this test// depend on which of the two ran first.    await using var context = CreateContext();    await SeedReferencedFuelsAsync(context);    await context.Database.ExecuteSqlRawAsync(        """        INSERT INTO fuel_offers (id, brand_id, fuel_type_id, data_kind, supplier_price_per_liter,        margin_uah_per_liter, created_at_utc, updated_at_utc, is_deleted)    VALUES ('keep-offer', 'upg', 'upg-keep', 'real', 58, 2, now(), now(), false)    """);        await context.Database.ExecuteSqlRawAsync(            """            INSERT INTO fuel_offer_volumes (id, offer_id, liters, price_override_uah, is_deleted,                                           created_at_utc, updated_at_utc)            VALUES ('keep-vol-live', 'keep-offer', 10, 600, false, now(), now()),                   ('keep-vol-dead', 'keep-offer', 20, 1200, true,  now(), now())            """);        var archived = await context.FuelOfferVolumes.IgnoreQueryFilters()            .CountAsync(v => v.OfferId == "keep-offer" && v.IsDeleted);        var visible = await context.FuelOfferVolumes            .CountAsync(v => v.OfferId == "keep-offer");        archived.Should().Be(1, "the archived volume is still there, just out of the catalogue");        visible.Should().Be(1, "and it is absent from the default query, without the offer being archived");        var offer = await context.FuelOffers.IgnoreQueryFilters().SingleAsync(o => o.Id == "keep-offer");        offer.IsDeleted.Should().BeFalse("one of its two volumes is still on sale");    }    [Fact]    public async Task TheSeedRows_CameThroughWithTheirPrices()    {        // A spot check that the backfill actually moved numbers, not just rows. 30 seeded offers from        // the 32 package rows (two of the fuel types share the 2 L and 3 L extras).        await using var context = CreateContext();        var okko95 = await context.FuelOffers.IgnoreQueryFilters()            .SingleAsync(o => o.BrandId == "okko" && o.FuelTypeId == "okko-95" && o.DataKind == DataKinds.Real);        okko95.FinalPerLiterWith(await MarginOf(okko95)).Should().Be(51m, "SeedData sets DiscountPrice, and the knobs derive it");        okko95.SupplierPricePerLiter.Should().Be(49m);        (await MarginOf(okko95)).Should().Be(2m, "the margin is the fuel's; the offer stopped keeping a copy");        var volumes = await context.FuelOfferVolumes.IgnoreQueryFilters()            .Where(v => v.OfferId == okko95.Id)            .Select(v => new { v.Liters })            .OrderBy(v => v.Liters)            .ToListAsync();        volumes.Should().HaveCount(3, "the seed gives okko-95 its 10/20/50 L nominals");        volumes.Select(v => v.Liters).Should().BeEquivalentTo([10m, 20m, 50m]);        // No stored total and no override: the 10 L nominal works out to 10 L at 51.00 through the        // offer's rate, which is the same number the seed used to write into a package_price column.        volumes.Should().OnlyContain(v => v.Liters > 0m);    }    /// <summary>    /// The margin an offer sells at, which is its fuel's - the same place production reads it since    /// the offer stopped carrying a copy.    /// </summary>    private async Task<decimal?> MarginOf(FuelOffer offer)    {        await using var lookup = CreateContext();        return await lookup.FuelTypes            .Where(f => f.Id == offer.FuelTypeId)            .Select(f => f.MarginUahPerLiter)            .FirstOrDefaultAsync();    }}